create or replace function public.dd_run_commercial_reconciliation() returns uuid language plpgsql security definer set search_path='public' as $$declare r uuid:=gen_random_uuid();nodes int:=0;edges int:=0;conf int:=0;begin insert into dd_commercial_intelligence_nodes(node_type,node_key,node_name,channel_code) select 'CHANNEL',c.code,c.name,c.code from dd_commercial_channels c where c.is_active on conflict(node_type,node_key) do update set node_name=excluded.node_name,channel_code=excluded.channel_code,updated_at=now();delete from dd_commercial_intelligence_nodes n where n.node_type='CHANNEL' and not exists(select 1 from dd_commercial_channels c where c.is_active and c.code=n.node_key);select count(*) into nodes from dd_commercial_intelligence_nodes;select count(*) into edges from dd_commercial_intelligence_edges;select count(*) into conf from dd_research_work_queue where status in('QUEUED','BLOCKED') and blocker in('CHANNEL_AUTHORITY_MISSING','CROSS_SELL_NOT_YET_GOVERNED');insert into dd_commercial_reconciliation_runs(id,status,nodes,edges,conflicts,research_created,owner_decisions,evidence,completed_at) values(r,case when conf>0 then 'PARTIAL' else 'GREEN' end,nodes,edges,conf,0,(select count(*) from dd_owner_attention_queue where status='OPEN'),jsonb_build_object('channel_authority','dd_commercial_channels','official_channels',(select jsonb_agg(code order by sort_order) from dd_commercial_channels where is_active),'b2b2c_is_relationship_model',true,'no_legacy_ch06_inference',true),now());return r;end$$;
